64	        .filter((name) => !names.includes(name))
65	        .join(" ");
66	    },
67	    contains: (name: string): boolean => this.x_ClassNames().includes(name),
68	    toggle: (name: string, force?: boolean): boolean => {
69	      const shouldAdd = force == null ? !this.classList.contains(name) : force;
70	      if (shouldAdd) {
71	        this.classList.add(name);
72	      } else {
73	        this.classList.remove(name);
