232	  public querySelectorAll(selector: string): FakeElement[]
233	  {
234	    const parts = selector.trim().split(/\s+/).filter(Boolean);
235	    const results: FakeElement[] = [];
236	    const stack: FakeElement[] = [this];
237	
238	    while (stack.length > 0) {
239	      const node = stack.shift();
240	      if (!node) {
241	        continue;
242	      }
243	
244	      if (parts.length === 1) {
245	        if (this.x_MatchesSelector(node, parts[0])) {
246	          results.push(node);
247	        }
248	      } else if (this.x_MatchesDescendantSelector(node, parts)) {
249	        results.push(node);
250	      }
251	
252	      stack.push(...node.children);
253	    }
254	
255	    return results;
256	  }
