258	  private x_ParseSimpleHtml(html: string): void
259	  {
260	    const tagRegex = /<([a-zA-Z][\w-]*)\b([^>]*)>/g;
261	    let match: RegExpExecArray | null = tagRegex.exec(html);
262	
263	    while (match) {
264	      const tagName = match[1];
265	      const attributes = match[2] || "";
266	      const element = new FakeElement(tagName);
267	      const classMatch = /\bclass="([^"]*)"/.exec(attributes);
268	      if (classMatch) {
269	        element.className = classMatch[1];
270	      }
271	      const hrefMatch = /\bhref="([^"]*)"/.exec(attributes);
272	      if (hrefMatch) {
273	        element.setAttribute("href", hrefMatch[1]);
274	      }
275	      const idMatch = /\bid="([^"]*)"/.exec(attributes);
276	      if (idMatch) {
277	        element.id = idMatch[1];
278	      }
279	      element.parentNode = this;
280	      this.children.push(element);
281	      match = tagRegex.exec(html);
282	    }
283	  }
284	
285	  private x_ClassNames(): string[]
286	  {
287	    return this.className.split(/\s+/).filter(Boolean);
288	  }
