290	  private x_MatchesSelector(node: FakeElement, selector: string): boolean
291	  {
292	    if (selector.startsWith(".")) {
293	      const className = selector.slice(1);
294	      return node.x_ClassNames().includes(className);
295	    }
296	
297	    if (selector.includes("[")) {
298	      const tagMatch = /^([a-zA-Z][\w-]*)/.exec(selector);
299	      const attrMatch = /\[([^\]=]+)(?:="([^"]*)")?\]/.exec(selector);
300	      if (tagMatch && node.tagName !== tagMatch[1].toUpperCase()) {
301	        return false;
302	      }
303	      if (attrMatch) {
304	        const attrValue = node.getAttribute(attrMatch[1]);
305	        if (attrMatch[2] != null) {
306	          return attrValue === attrMatch[2];
307	        }
308	        return attrValue != null;
309	      }
310	    }
311	
312	    return node.tagName === selector.toUpperCase();
313	  }
314	
315	  private x_MatchesDescendantSelector(node: FakeElement, parts: string[]): boolean
316	  {
317	    if (!this.x_MatchesSelector(node, parts[parts.length - 1])) {
318	      return false;
319	    }
320	
321	    let current: FakeElement | null = node;
322	    for (let index = parts.length - 2; index >= 0; index -= 1) {
323	      let found = false;
324	      let parent: FakeElement | null = current ? current.parentNode : null;
325	      while (parent) {
326	        if (this.x_MatchesSelector(parent, parts[index])) {
327	          found = true;
328	          current = parent;
329	          break;
330	        }
331	        parent = parent.parentNode;
332	      }
333	      if (!found) {
334	        return false;
335	      }
336	    }
337	
338	    return true;
339	  }
340	}
