491	            supported: true,
492	            contentType: "text/markdown",
493	          },
494	          {
495	            name: "other.md",
496	            path: "docs/other.md",
497	            kind: "file",
498	            supported: true,
499	            contentType: "text/markdown",
500	          },
501	        ],
502	      });
503	    }
