537	function LoadChatHarness(options?: {
538	  fetch?: (path: string, request?: Record<string, unknown>) => Promise<FakeFetchResponse>;
539	  hash?: string;
540	  touch?: boolean;
541	  markdown?: boolean;
542	}): ChatHarness
543	{
544	  const document = new FakeDocument();
545	  const pendingFrames: Array<(() => void) | null> = [];
546	  const pendingTimers: Array<(() => void) | null> = [];
547	  const windowListeners: Record<string, Listener[]> = {};
548	  const location = {
549	    hash: options?.hash || "#/piles/default/sessions/sess-1",
550	    protocol: "http:",
551	    host: "127.0.0.1:9004",
552	  };
553	  let idCounter = 0;
554	
555	  FakeWebSocket.instances = [];
556	
557	  const context: Record<string, any> = {
558	    console,
559	    URLSearchParams,
560	    WebSocket: FakeWebSocket,
561	    document,
562	    location,
563	    fetch:
564	      options?.fetch ||
565	      (async (path: string) => DefaultFileFetch(path) || JsonResponse({})),
566	    localStorage: {
567	      getItem: () => null,
568	      setItem: () => undefined,
569	    },
570	    crypto: {
571	      randomUUID: () => {
572	        idCounter += 1;
573	        return "test-id-" + idCounter;
574	      },
575	    },
576	    matchMedia: () => ({ matches: options?.touch === true }),
577	    requestAnimationFrame: (callback: () => void): number => {
578	      pendingFrames.push(callback);
579	      return pendingFrames.length;
580	    },
581	    cancelAnimationFrame: (id: number): void => {
582	      pendingFrames[id - 1] = null;
583	    },
584	    setTimeout: (callback: () => void): number => {
585	      pendingTimers.push(callback);
586	      return pendingTimers.length;
587	    },
588	    clearTimeout: (id: number): void => {
589	      pendingTimers[id - 1] = null;
590	    },
591	    addEventListener: (type: string, handler: Listener): void => {
592	      windowListeners[type] = windowListeners[type] || [];
593	      windowListeners[type].push(handler);
594	    },
595	    removeEventListener: (type: string, handler: Listener): void => {
596	      windowListeners[type] = (windowListeners[type] || []).filter(
597	        (entry) => entry !== handler,
598	      );
599	    },
600	  };
601	  context.window = context;
602	  context.globalThis = context;
603	  if (options?.touch === true) {
604	    context.ontouchstart = null;
605	  }
606	
607	  vm.createContext(context);
608	  if (options?.markdown !== false) {
609	    context.markdownit = markdownit;
610	    context.katex = katex;
611	    vm.runInContext(fs.readFileSync(x_sheafMarkdownJsPath, "utf8"), context);
612	  }
613	  vm.runInContext(fs.readFileSync(x_aguiChatJsPath, "utf8"), context);
614	
615	  const handles: any[] = [];
616	  const originalCreate = context.ChatView.create;
617	  context.ChatView.create = function (...args: unknown[]): unknown {
618	    const handle = originalCreate.apply(context.ChatView, args);
619	    handles.push(handle);
620	    return handle;
621	  };
622	
623	  vm.runInContext(fs.readFileSync(x_sheafChatJsPath, "utf8"), context);
624	
625	  return {
626	    app: document.app,
627	    document,
628	    location,
629	    sockets: FakeWebSocket.instances,
630	    handles,
631	    flushAnimationFrames: () => {
632	      while (pendingFrames.length > 0) {
633	        const callback = pendingFrames.shift();
634	        if (callback) {
635	          callback();
636	        }
637	      }
638	    },
639	    runTimers: () => {
640	      while (pendingTimers.length > 0) {
641	        const callback = pendingTimers.shift();
642	        if (callback) {
643	          callback();
644	        }
645	      }
646	    },
647	  };
648	}
