650	function Frames(socket: FakeWebSocket, kind?: string): Array<Record<string, any>>
651	{
652	  const frames = socket.sent.map((data) => JSON.parse(data) as Record<string, any>);
653	  return kind ? frames.filter((frame) => frame.kind === kind) : frames;
654	}
655	
656	function LastFrame(socket: FakeWebSocket, kind: string): Record<string, any>
657	{
658	  const frames = Frames(socket, kind);
659	  assert.ok(frames.length > 0, "expected at least one " + kind + " frame");
660	  return frames[frames.length - 1];
661	}
