663	function ServerEnvelope(
664	  kind: string,
665	  payload: unknown,
666	  sequence?: number,
667	): Record<string, unknown>
668	{
669	  const envelope: Record<string, unknown> = {
670	    v: 1,
671	    id: "server-" + kind + "-" + String(sequence || "unsequenced"),
672	    kind,
673	    pile: "default",
674	    sessionId: "sess-1",
675	    timestamp: "2026-06-08T00:00:00.000Z",
676	    payload,
677	  };
678	  if (sequence != null) {
679	    envelope.sequence = sequence;
680	  }
681	  return envelope;
682	}
